/*
 * A136717  Triangle T(n,k), 1 <= k <= n, read by rows: T(n,k) is the number
 *          of permutations in the symmetric group S_n having k multiplicative
 *          3-excedances. Equivalently, the number of permutations of the set
 *          {3,6,9,...,3n} with k excedances.
 * https://oeis.org/A136717
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   a(n) is the nth element of the triangle T(n,k) generated by: *
 *            T(1,1) = 1 * T(n,0) = 0 , T(0,k) = 0 * * Recurrence (Jansson,
 *            Proposition 2.2): * n = 3t : T(n,k) = (k+1-2t) T(n-1,k) + (5t-k)
 *            T(n-1,k-1) * n = 3t+1 : T(n,k) = (k-2t) T(n-1,k) + (5t+2-k)
 *            T(n-1,k-1) * n = 3t+2 : T(n,k) = (k-1-2t) T(n-1...
 * Range:     u8 n <= 19, u16 n <= 42, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* static storage for rows of the triangle */
static seq_t **T = NULL;
static idx_t max_rows = 0;   /* number of rows that have been generated */

/* ensure rows 1..upto are computed */
static void ensure_rows(idx_t upto)
{
    if (upto <= max_rows)
        return;

    /* enlarge pointer array */
    seq_t **newT = (seq_t **)realloc(T, sizeof(seq_t *) * (upto + 1));
    if (!newT) return;          /* allocation failure – caller receives garbage */
    T = newT;

    /* allocate new rows and zero‑initialize them */
    for (idx_t n = max_rows + 1; n <= upto; ++n) {
        seq_t *row = (seq_t *)calloc(n + 1, sizeof(seq_t)); /* indices 0..n, index 0 unused */
        if (!row) return;          /* allocation failure */
        T[n] = row;
    }

    /* base case: T(1,1) = 1 */
    if (max_rows == 0) {
        T[1][1] = 1;
    }

    /* compute rows beyond the ones already present */
    for (idx_t n = max_rows + 1; n <= upto; ++n) {
        if (n == 1) continue;   /* already set */
        seq_t *curr = T[n];
        seq_t *prev = T[n - 1];
        idx_t t  = n / 3;
        idx_t r3 = n % 3;
        idx_t L  = n - n / 3;    /* smallest k with non‑zero value */

        for (idx_t k = L; k <= n; ++k) {
            seq_t term1 = 0, term2 = 0;
            seq_t coef1, coef2;

            if (r3 == 0) {                /* n = 3t   */
                coef1 = (k + 1) - 2 * t;
                coef2 = 5 * t - k;
            } else if (r3 == 1) {           /* n = 3t+1 */
                coef1 = k - 2 * t;
                coef2 = 5 * t + 2 - k;
            } else {                        /* r3 == 2, n = 3t+2 */
                coef1 = k - 1 - 2 * t;
                coef2 = 5 * t + 4 - k;
            }

            if (k <= n - 1)
                term1 = coef1 * prev[k];
            if (k >= 2)   /* k-1 >= 1 */
                term2 = coef2 * prev[k - 1];

            curr[k] = term1 + term2;
        }
    }

    max_rows = upto;
}

seq_t a(idx_t n)
{
    if (n < 1)
        return 0;      /* sequence starts at a(1) */

    /* locate the row r such that r*(r+1)/2 >= n > (r-1)*r/2 */
    idx_t r = 1;
    while ((r * (r + 1)) / 2 < n)
        ++r;

    idx_t k = n - (r * (r - 1)) / 2;   /* column index in row r */

    ensure_rows(r);
    return T[r][k];
}
